size_t BLOCK_MB = 256;
size_t BLOCK_SIZE = BLOCK_MB * 1024 * 1024;
char* current_ptr = NULL;
size_t allocated_bytes = 0;

// Repeatedly allocate until system limits are reached (malloc fails)
while (1) {
    current_ptr = (char*)malloc(BLOCK_SIZE);

    if (current_ptr == NULL) {
        break; // System limit hit (OOM)
    }

    // Pointer arithmetic access to ensure memory is committed
    current_ptr[0] = 1;
    current_ptr[BLOCK_SIZE - 1] = 1;

    allocated_bytes += BLOCK_SIZE;
}
// allocated_bytes holds the system's probed process limit
